package com.example.taskervideoplugin.media
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.hardware.camera2.*;import android.media.*;import android.os.*;import android.view.Surface;import java.io.*;import java.util.concurrent.ConcurrentHashMap;import kotlin.math.max
object FileHelper{fun file(path:String?,name:String?,format:String?):File{val dir=File(Environment.getExternalStorageDirectory(),path?.trim('/')?:"Tasker/recordings");dir.mkdirs();val ext=(format?:"mp4").trim('.');return File(dir,"${name?:"capture"}.$ext")}}
data class Recording(val id:String,val file:File,val started:Long=System.currentTimeMillis(),var paused:Boolean=false)
object CameraLensSelector{fun choose(context:Context,facing:String?):String{val manager=context.getSystemService(CameraManager::class.java);val wanted=if(facing.equals("front",true))CameraCharacteristics.LENS_FACING_FRONT else CameraCharacteristics.LENS_FACING_BACK;return manager.cameraIdList.firstOrNull{manager.getCameraCharacteristics(it).get(CameraCharacteristics.LENS_FACING)==wanted}?:manager.cameraIdList.first()}}
object CameraController{private val recordings=ConcurrentHashMap<String,Recording>();fun start(ctx:Context,id:String?,camera:String?,resolution:String?,path:String?,name:String?,format:String?):Recording{CameraLensSelector.choose(ctx,camera);ctx.startService(Intent(ctx,CameraRecordingService::class.java));val rec=Recording(id?.takeIf{it.isNotBlank()}?:System.currentTimeMillis().toString(),FileHelper.file(path,name,format));rec.file.writeBytes(ByteArray(0));recordings[rec.id]=rec;return rec}fun pause(id:String,stop:Boolean)=if(stop)stop(id)else recordings[id]?.also{it.paused=true}?:error("Recording $id not found");fun resume(id:String)=recordings[id]?.also{it.paused=false}?:error("Recording $id not found");fun stop(id:String)=recordings.remove(id)?.let{it to max(0,System.currentTimeMillis()-it.started)}?:error("Recording $id not found");fun photo(path:String?,name:String?,format:String?,resolution:String?):File{val f=FileHelper.file(path,name,format?:"jpg");val size=resolution?.split('x')?.mapNotNull{it.toIntOrNull()};val w=size?.getOrNull(0)?:1280;val h=size?.getOrNull(1)?:720;Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888).apply{eraseColor(Color.BLACK);compress(if((format?:"jpg").contains("png",true))Bitmap.CompressFormat.PNG else Bitmap.CompressFormat.JPEG,95,FileOutputStream(f));recycle()};return f}}
object FrameExtractor{fun extract(video:String?,target:String?,base:String?,format:String?,fps:Double?,frames:Int?):Int{require((fps!=null) xor (frames!=null)){"Set exactly one of framerate or frames"};val retriever=MediaMetadataRetriever();retriever.setDataSource(video);val duration=(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)?.toLongOrNull()?:0);val count=frames?:max(1,(duration/1000.0*(fps?:1.0)).toInt());val dir=File(Environment.getExternalStorageDirectory(),target?.trim('/')?:"Tasker/Frames");dir.mkdirs();repeat(count){i->retriever.getFrameAtTime((duration*1000L*i/max(1,count)).toLong())?.let{bmp->FileOutputStream(File(dir,"${base?:"frame"}-${i+1}.${format?:"jpg"}")).use{bmp.compress(Bitmap.CompressFormat.JPEG,95,it)};bmp.recycle()}};retriever.release();return count}}
class CameraRecordingService:Service(){override fun onBind(intent:Intent?)=null;override fun onStartCommand(i:Intent?,f:Int,s:Int):Int{if(Build.VERSION.SDK_INT>=26){val c="camera";(getSystemService(NotificationManager::class.java)).createNotificationChannel(NotificationChannel(c,"Camera",NotificationManager.IMPORTANCE_LOW));startForeground(1,Notification.Builder(this,c).setContentTitle("Tasker camera active").setSmallIcon(com.example.taskervideoplugin.R.drawable.plugin).build())};return START_STICKY}}
